import torch, torch.nn.functional as F, math
def gen(B, C=96, H=56, W=56, seed=0):
    g = torch.Generator(device='cuda').manual_seed(seed)
    r = lambda *s: torch.randn(*s, generator=g, device='cuda')
    x = r(B,C,H,W); dww = r(C,1,7,7)/math.sqrt(7); dwb = r(C); lnw = torch.ones(C,device='cuda'); lnb = torch.zeros(C,device='cuda')
    w1 = r(4*C,C)/math.sqrt(C); b1 = r(4*C); gw = r(1,1,1,4*C)/math.sqrt(4*C); gb = r(1,1,1,4*C)/math.sqrt(4*C); w2 = r(C,4*C)/math.sqrt(4*C); b2 = r(C)
    return [x,dww,dwb,lnw,lnb,w1,b1,gw,gb,w2,b2,1e-6,1e-6]
def ref(x,dww,dwb,lnw,lnb,w1,b1,gw,gb,w2,b2,eps,lneps, dt=torch.float64):
    a=[t.to(dt) if torch.is_tensor(t) else t for t in (x,dww,dwb,lnw,lnb,w1,b1,gw,gb,w2,b2)]
    x,dww,dwb,lnw,lnb,w1,b1,gw,gb,w2,b2=a; C=x.shape[1]
    d = F.conv2d(x,dww,dwb,padding=3,groups=C).permute(0,2,3,1)
    d = F.layer_norm(d,(C,),lnw,lnb,lneps)
    h = F.gelu(d@w1.T+b1)
    gx = torch.norm(h,p=2,dim=(1,2),keepdim=True); nx = gx/(gx.mean(dim=-1,keepdim=True)+eps)
    h = gw*(h*nx)+gb+h
    return x + (h@w2.T+b2).permute(0,3,1,2)
''')
