      __threadfence();
      red_release(ctr + 6, 1u);
      while (ld_acquire(ctr + 6) < gridDim.x) { }
      asm volatile("fence.proxy.async;" ::: "memory");
      mbar_expect(bar_w1, W1IMG);
#pragma unroll
