        }
#pragma unroll
        for (int m = 0; m < 4; m++) {
          const int ti = i - 2 * m;
          if (ti >= 0 && ti < 7) {
#pragma unroll
            for (int cc = 0; cc < 4; cc++)
#pragma unroll
              for (int j = 0; j < 7; j++) acc[m][cc] = fmaf(xr[cc + 1 + j], tap[ti * 7 + j], acc[m][cc]);
          }
        }
      }
      const float bias = s_dwb[c];
#pragma unroll
      for (int m = 0; m < 4; m++)
#pragma unroll
        for (int cc = 0; cc < 4; cc++) acc[m][cc] += bias;
