        a += __shfl_xor_sync(0xffffffffu, a, 2); b += __shfl_xor_sync(0xffffffffu, b, 2);
        a += __shfl_xor_sync(0xffffffffu, a, 16); b += __shfl_xor_sync(0xffffffffu, b, 16);
        ps[e] = a; pq[e] = b;
      }
      if ((lane & 0x13) == 0) {
#pragma unroll
        for (int m = 0; m < 4; m++)
#pragma unroll
          for (int cc = 0; cc < 4; cc++) {
            const int t = (pp + 2 * m) * 8 + 4 * ch + cc;
